CREATE TABLE IF NOT EXISTS households (id INT AUTO_INCREMENT PRIMARY KEY, kk_number VARCHAR(32) NOT NULL UNIQUE, address VARCHAR(255) NOT NULL, rt VARCHAR(5), rw VARCHAR(5), head_resident_id INT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (head_resident_id) REFERENCES resident_profiles(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS household_members (id INT AUTO_INCREMENT PRIMARY KEY, household_id INT NOT NULL, resident_id INT NOT NULL UNIQUE, relationship VARCHAR(60) NOT NULL, FOREIGN KEY (household_id) REFERENCES households(id) ON DELETE CASCADE, FOREIGN KEY (resident_id) REFERENCES resident_profiles(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS business_categories (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS resident_businesses (id INT AUTO_INCREMENT PRIMARY KEY, owner_id INT NOT NULL, category_id INT NOT NULL, name VARCHAR(150) NOT NULL, description TEXT, whatsapp VARCHAR(25), whatsapp_public TINYINT(1) NOT NULL DEFAULT 0, address VARCHAR(255), photo_url VARCHAR(500), latitude DECIMAL(10,7), longitude DECIMAL(10,7), status ENUM('pending','published','disabled') NOT NULL DEFAULT 'pending', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (owner_id) REFERENCES resident_profiles(id) ON DELETE RESTRICT, FOREIGN KEY (category_id) REFERENCES business_categories(id) ON DELETE RESTRICT, INDEX idx_business_name (name), INDEX idx_business_status (status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS village_locations (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL, category VARCHAR(80), latitude DECIMAL(10,7) NOT NULL, longitude DECIMAL(10,7) NOT NULL, is_public TINYINT(1) DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
